+import React, { useState, useEffect } from 'react';
+import {
+  Alert,
+  Image,
+  Pressable,
+  Switch,
+  TextInput,
+  TouchableOpacity,
+  View,
+  ActivityIndicator,
+} from 'react-native';
+import { useRouter } from 'expo-router';
+import tw from 'twrnc';
+import AsyncStorage from '@react-native-async-storage/async-storage';
+import Ionicons from 'react-native-vector-icons/Ionicons';
+import { ThemedView } from '@/components/ThemedView';
+import { ThemedText } from '@/components/ThemedText';
+import { useThemeColor } from '@/hooks/useThemeColor';
+import axios from 'axios';
+import Constants from 'expo-constants';
+
+const logo = require('../../assets/images/logo.png');
+
+export default function LoginForm() {
+  const router = useRouter();
+
+  // Ensure theme colors have defaults
+  const theme = useThemeColor({}, 'text') || '#070c70';
+  const backgroundColor = useThemeColor({}, 'background') || '#ffffff';
+  const placeholderColor = useThemeColor({}, 'placeholder') || '#aaa';
+  const primaryColor = useThemeColor({}, 'primary') || '#ff1493';
+
+  const [rememberMe, setRememberMe] = useState(false);
+  const [username, setUsername] = useState('');
+  const [password, setPassword] = useState('');
+  const [isPasswordVisible, setPasswordVisible] = useState(false);
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState('');
+  const apiUrl = Constants.expoConfig?.extra?.API_BASE_URL;
+
+  useEffect(() => {
+    const loadCredentials = async () => {
+      try {
+        const savedUsername = await AsyncStorage.getItem('username');
+        const savedPassword = await AsyncStorage.getItem('password');
+        if (savedUsername && savedPassword) {
+          setUsername(savedUsername);
+          setPassword(savedPassword);
+          setRememberMe(true);
+        }
+      } catch (err) {
+        console.error('Failed to load credentials:', err);
+      }
+    };
+    loadCredentials();
+  }, []);
+
+  const togglePasswordVisibility = () => {
+    setPasswordVisible((prev) => !prev);
+  };
+
+  const handleLogin = async () => {
+    if (!username.trim() || !password.trim()) {
+      setError('Please fill in all fields.');
+      return;
+    }
+
+    setLoading(true);
+    setError('');
+    try {
+      const response = await axios.post(`${apiUrl}/login`, {
+        username,
+        password,
+      });
+
+      if (response.status === 200) {
+        if (rememberMe) {
+          await AsyncStorage.setItem('username', username);
+          await AsyncStorage.setItem('password', password);
+        } else {
+          await AsyncStorage.removeItem('username');
+          await AsyncStorage.removeItem('password');
+        }
+        router.push('/tab/main');
+      } else {
+        setError('Invalid username or password.');
+      }
+    } catch (err) {
+      setError('Login failed. Please try again.');
+      console.error('Login failed:', err.message);
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <ThemedView style={tw`flex-1 items-center`} accessibilityLabel="Login Screen">
+      <Image source={logo} style={tw`h-40 w-42 mb-10 mt-20`} resizeMode="contain" />
+
+      {/* Input Fields */}
+      <ThemedView style={tw`w-full px-10 mb-4 gap-4`}>
+        {/* Username Input */}
+        <TextInput
+          style={[
+            tw`h-12 px-5 border rounded-md text-lg`,
+            {
+              backgroundColor,
+              color: theme,
+              borderColor: theme,
+            },
+          ]}
+          placeholder="Username"
+          placeholderTextColor={placeholderColor}
+          value={username}
+          onChangeText={(text) => {
+            setUsername(text);
+          }}
+          autoCorrect={false}
+          autoCapitalize="none"
+        />
+
+        {/* Password Input */}
+        <View style={tw`relative`}>
+          <TextInput
+            style={[
+              tw`h-12 px-5 border rounded-md text-lg pr-12`, // Increased padding to avoid overlap
+              {
+                backgroundColor,
+                color: theme,
+                borderColor: theme,
+              },
+            ]}
+            placeholder="Password"
+            placeholderTextColor={placeholderColor}
+            secureTextEntry={!isPasswordVisible}
+            value={password}
+            onChangeText={(text) => {
+              setPassword(text);
+            }}
+            autoCorrect={false}
+            autoCapitalize="none"
+          />
+          {/* Eye Icon for Password Visibility */}
+          <TouchableOpacity
+            onPress={togglePasswordVisibility}
+            style={tw`absolute right-3 top-3 h-6 w-6 justify-center items-center`}
+            accessibilityLabel="Toggle password visibility"
+          >
+            <Ionicons
+              name={isPasswordVisible ? 'eye-off' : 'eye'}
+              size={22}
+              color={theme}
+            />
+          </TouchableOpacity>
+        </View>
+      </ThemedView>
+
+      {/* Remember Me and Forgot Password */}
+      <ThemedView style={tw`w-full px-12 flex-row justify-between items-center mb-4`}>
+        <View style={tw`flex-row items-center`}>
+          <Switch
+            value={rememberMe}
+            onValueChange={setRememberMe}
+            trackColor={{ true: primaryColor, false: 'gray' }}
+          />
+          <ThemedText style={tw`text-xs ml-2`}>Remember Me</ThemedText>
+        </View>
+        <Pressable onPress={() => router.push('/auth/reset')} accessibilityLabel="Forgot Password">
+          <ThemedText style={tw`text-xs text-[${primaryColor}]`}>
+            Forgot Password?
+          </ThemedText>
+        </Pressable>
+      </ThemedView>
+
+      {/* Login Button */}
+      <ThemedView style={tw`w-full px-12`}>
+        <Pressable
+          style={[
+            tw`h-11 border rounded-md items-center justify-center`,
+            { backgroundColor: primaryColor, borderColor: theme },
+          ]}
+          onPress={handleLogin}
+          disabled={loading}
+        >
+          {loading ? (
+            <ActivityIndicator color={theme} />
+          ) : (
+            <ThemedText style={tw`text-lg font-bold text-white`}>Login</ThemedText>
+          )}
+        </Pressable>
+
+        {error && (
+          <ThemedText style={tw`text-red-500 text-center mt-2`}>
+            {error}
+          </ThemedText>
+        )}
+
+        <ThemedText style={tw`text-center py-2 text-xs`}>OR LOGIN WITH</ThemedText>
+      </ThemedView>
+
+      {/* Sign Up Link */}
+      <ThemedText style={tw`text-center`}>
+        Don't Have an Account?{' '}
+        <ThemedText
+          style={tw`text-[${primaryColor}] text-xs`}
+          onPress={() => router.push('/auth/signup')}
+          accessibilityLabel="Sign Up"
+        >
+          Sign Up
+        </ThemedText>
+      </ThemedText>
+    </ThemedView>
+  );
+}

